import { ADD, DELETE, EDIT, FILTER } from "../types/productTypes";

const addProduct = (payload) => ({
  type: ADD,
  payload,
});

const editProduct = (payload) => ({
  type: EDIT,
  payload,
});

const deleteProduct = (payload) => ({
  type: DELETE,
  payload,
});

export { addProduct, editProduct, deleteProduct };
